import { gsap } from 'gsap';
import {
  MeshPhysicalNodeMaterial,
  MeshBasicNodeMaterial,
} from 'three/webgpu';
import { uv, vec2, color, mix, smoothstep, float } from 'three/tsl';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const {
    Group,
    Mesh,
    PlaneGeometry,
    CylinderGeometry,
    OctahedronGeometry,
    CircleGeometry,
    DirectionalLight,
    Color,
    MathUtils,
    DoubleSide,
  } = THREE;

  const root = new Group();
  root.userData.handlers = {};

  const palette = {
    background: '#0b0b10',
    surface: '#101017',
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    coolRim: '#9fb0c4',
  };

  const disposables = [];
  const timelines = [];

  // ---------------------------------------------------------------
  // BACKDROP — solid dark background plane (fixed palette)
  // ---------------------------------------------------------------
  const backdropGeo = new PlaneGeometry(7, 6);
  const backdropMat = new MeshBasicNodeMaterial();
  {
    // Use a constant dark color matching the spec palette
    backdropMat.colorNode = color(palette.background);
  }
  const backdrop = new Mesh(backdropGeo, backdropMat);
  backdrop.position.set(0, 0, -2.5);
  root.add(backdrop);
  disposables.push(backdropGeo, backdropMat);

  // ---------------------------------------------------------------
  // PRISM GROUP (subject) — dispersive glass
  // ---------------------------------------------------------------
  const prismGroup = new Group();
  prismGroup.position.set(0, 0.15, 0);
  root.add(prismGroup);

  const sideLen = 1.2;
  const radius = sideLen / Math.sqrt(3);
  const prismGeo = new CylinderGeometry(radius, radius, 1.8, 3, 1, false);
  const prismMat = new MeshPhysicalNodeMaterial({
    color: new Color(palette.paper),
    metalness: 0.0,
    roughness: 0.08,
    transmission: 1.0,
    thickness: 0.9,
    ior: 1.55,
    clearcoat: 0.25,
    clearcoatRoughness: 0.1,
    iridescence: 1.0,
    iridescenceIOR: 1.3,
    iridescenceThicknessRange: [120, 480],
    attenuationColor: new Color(palette.paper),
    attenuationDistance: 2.5,
    side: DoubleSide,
  });
  // dispersion pass — split refraction across RGB
  prismMat.dispersion = 0.18;

  const prismMesh = new Mesh(prismGeo, prismMat);
  // axis horizontal + spec rotation (12deg z, 20deg y)
  prismMesh.rotation.z = MathUtils.degToRad(90 + 12);
  prismMesh.rotation.y = MathUtils.degToRad(20);
  prismGroup.add(prismMesh);
  disposables.push(prismGeo, prismMat);

  // ---------------------------------------------------------------
  // EMISSIVE CORE — octahedron inside prism
  // ---------------------------------------------------------------
  const coreGeo = new OctahedronGeometry(0.35, 0);
  const coreMat = new MeshPhysicalNodeMaterial({
    color: new Color(palette.accent),
    roughness: 0.4,
    metalness: 0.0,
  });
  coreMat.emissiveNode = color(palette.accent).mul(float(2.2));
  const core = new Mesh(coreGeo, coreMat);
  prismGroup.add(core);
  disposables.push(coreGeo, coreMat);

  // ---------------------------------------------------------------
  // BACK RIM LIGHT — cool directional, behind-left
  // ---------------------------------------------------------------
  const rimLight = new DirectionalLight(new Color(palette.coolRim), 1.4);
  rimLight.position.set(-3.2, 1.6, -2.4);
  rimLight.target.position.set(0, 0.1, 0);
  root.add(rimLight);
  root.add(rimLight.target);

  // ---------------------------------------------------------------
  // CONTACT SHADOW — radial, under prism
  // ---------------------------------------------------------------
  const shadowGeo = new CircleGeometry(1.35, 40);
  const shadowMat = new MeshBasicNodeMaterial({ transparent: true });
  {
    const centered = uv().sub(vec2(0.5, 0.5));
    const dist = centered.length();
    shadowMat.colorNode = color(palette.ink);
    shadowMat.opacityNode = smoothstep(0.5, 0.0, dist).mul(float(0.5));
  }
  const contactShadow = new Mesh(shadowGeo, shadowMat);
  contactShadow.rotation.x = -Math.PI / 2;
  contactShadow.position.set(0, -1.14, 0.35);
  root.add(contactShadow);
  disposables.push(shadowGeo, shadowMat);

  // ---------------------------------------------------------------
  // CAUSTIC STREAK — dispersed gradient on floor
  // ---------------------------------------------------------------
  const causticGeo = new PlaneGeometry(2.4, 0.5);
  const causticMat = new MeshBasicNodeMaterial({ transparent: true });
  {
    const t = uv().x;
    const s0 = color(palette.accent);
    const s1 = color(palette.paper);
    const s2 = color(palette.coolRim);
    const a = mix(s0, s1, smoothstep(0.2, 0.5, t));
    const b = mix(a, s2, smoothstep(0.5, 0.8, t));
    causticMat.colorNode = b;
    causticMat.opacityNode = float(0.35);
  }
  const caustic = new Mesh(causticGeo, causticMat);
  caustic.rotation.x = -Math.PI / 2;
  caustic.position.set(0, -1.1, 0.6);
  root.add(caustic);
  disposables.push(causticGeo, causticMat);

  // ---------------------------------------------------------------
  // TEXT — headline + caption
  // ---------------------------------------------------------------
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const headlineItem = items.find((i) => i.role === 'headline');
  const captionItem = items.find((i) => i.role === 'caption');

  const headlineText = ctx.fontAtlas.createText(
    headlineItem ? headlineItem.text : 'Light, machined.',
    {
      fontSize: 68,
      color: palette.paper,
      align: 'center',
      letterSpacingPx: -0.34,
    }
  );
  headlineText.position.set(0, -1.75, 0.1);
  root.add(headlineText);

  const captionText = ctx.fontAtlas.createText(
    captionItem ? captionItem.text : 'SAPPHIRE OVER DIAL / ZERO DISTORTION',
    {
      fontSize: 18,
      color: palette.paper,
      align: 'center',
      letterSpacingPx: 1.44,
    }
  );
  captionText.position.set(0, -2.25, 0.1);
  root.add(captionText);

  // ---------------------------------------------------------------
  // IDLE MOTION — slow breathing (<=2%)
  // ---------------------------------------------------------------
  const breatheTl = gsap.timeline({ repeat: -1, yoyo: true });
  breatheTl.to(prismGroup.scale, {
    x: 1.02,
    y: 1.02,
    z: 1.02,
    duration: 3.2,
    ease: 'sine.inOut',
  });
  timelines.push(breatheTl);

  // ---------------------------------------------------------------
  // CINEMATIC PRIMITIVE — depth-rotate on hover
  // ---------------------------------------------------------------
  const depthRotatePrim = ctx.primitives['depth-rotate'](prismGroup, {
    maxDeg: 10,
    trigger: 'hover',
  });

  root.userData.handlers.pointerover = () => {
    gsap.to(caustic.scale, { x: 1.08, duration: 0.35, ease: 'power2.out' });
    if (depthRotatePrim?.timeline?.play) depthRotatePrim.timeline.play();
  };
  root.userData.handlers.pointerout = () => {
    gsap.to(caustic.scale, { x: 1.0, duration: 0.9, ease: 'power4.out' });
    if (depthRotatePrim?.timeline?.reverse) depthRotatePrim.timeline.reverse();
  };

  // ---------------------------------------------------------------
  // ENTRANCE — weighted settle
  // ---------------------------------------------------------------
  prismGroup.scale.set(0.96, 0.96, 0.96);
  const entranceTl = gsap.timeline();
  entranceTl.to(prismGroup.scale, {
    x: 1.04,
    y: 1.04,
    z: 1.04,
    duration: 0.6,
    ease: 'power3.out',
  }).to(prismGroup.scale, {
    x: 1.0,
    y: 1.0,
    z: 1.0,
    duration: 0.9,
    ease: 'power4.out',
  });
  timelines.push(entranceTl);

  // ---------------------------------------------------------------
  // CLEANUP
  // ---------------------------------------------------------------
  root.userData.cleanup = () => {
    timelines.forEach((tl) => tl.kill());
    if (depthRotatePrim?.cleanup) depthRotatePrim.cleanup();
    disposables.forEach((d) => {
      if (d && typeof d.dispose === 'function') d.dispose();
    });
    if (headlineText?.userData?.cleanup) headlineText.userData.cleanup();
    if (captionText?.userData?.cleanup) captionText.userData.cleanup();
    gsap.killTweensOf(caustic.scale);
    gsap.killTweensOf(prismGroup.scale);
  };

  return root;
}
